\label{thm:consensus time large alphanorm}
 The consensus time of 3-Majority starting from any initial configuration provided that $\gamma_0 \ge \frac{C\log n}{\sqrt{n}}$ for a sufficiently large constant $C>0$ is $O\qty(\frac{\log n}{\gamma_0})$ with high probability.

 Similarly, the consensus time of 2-Choices starting from any initial configuration provided that $\gamma_0 \ge \frac{C(\log n)^2}{n}$ for a sufficiently large constant $C>0$ is $O\qty(\frac{\log n}{\gamma_0})$ with high probability.

For example, a straightforward calculation (also used in previous works~\cite{simple_dynamics,stabilizing_consensus,nearly_tight_analysis,ignore_or_comply}; see \cref{lem:basic inequality} for details) shows that the expectation of $\alpha_t(i)$ conditioned on the configuration at round $t-1$ satisfies
\begin{align}
  \mathbb{E}_{t-1}[\alpha_t(i)] = \alpha_{t-1}(i)(1+\alpha_{t-1}(i) - \gamma_{t-1}) \label{eq:expectation of alpha intro}.
\end{align}

\label{lem:weak opinion vanishing intro}
 Consider 3-Majority starting from an initial configuration with $\gamma_0 \ge \frac{C\log n}{\sqrt{n}}$ for a sufficiently large constant $C>0$.
 If an opinion $i$ is weak at round $0$, then $\alpha_T(i) = 0$ with probability $1-O(n^{-3})$ for some $T = O\qty(\frac{\log n}{\gamma_0})$.

It is easy to see that, for 3-Majority, for any $v\in V$, $i\in [k]$ and $t\geq 1$, 
  \begin{align}
      \Pr_{t-1}\sbra*{\mathsf{opn}_t(v)=i}
      =\alpha_{t-1}(i)^2+\left(1-\gamma_{t-1}\right)\alpha_{t-1}(i)
      =\alpha_{t-1}(i)\rbra*{1+\alpha_{t-1}(i)-\gamma_{t-1}}.
      \label{eq:updating probability for 3Majority}
  \end{align}

\label{def:Bernstein condition}
Let $D,s\ge 0$ be parameters.
A random variable $X$ satisfies \emph{$(D,s)$-Bernstein condition} if,
for any $\lambda\in \mathbb{R}$ such that $\abs{\lambda} D < 3$, 
$\mathbb{E}\qty[ \mathrm{e}^{\lambda X} ]  \le \exp\qty( \frac{\lambda^2 s / 2}{1- (\abs{\lambda}D)/3})$.
We say that $X$ satisfies \emph{one-sided} $(D,s)$-Bernstein condition if,
for any $\lambda\geq 0$ such that $\lambda D < 3$, 
$\mathbb{E}\qty[ \mathrm{e}^{\lambda X} ]  \le \exp\qty( \frac{\lambda^2 s / 2}{1- (\lambda D)/3})$.

\label{lem:Bernstein condition}


Let $X,Y$ be random variables. We have the following:
\begin{enumerate}

    \item \label{item:Bernstein condition for bounded random variables}
    If $\mathbb{E}[X]=0$ and $\abs{X}\leq D$ for some $D$, then $X$ satisfies $\qty(D,\mathbf{Var}\qty[X])$-Bernstein condition.
    \item \label{item:Bernstein condition 1}
    If $X$ satisfies $\qty(D,s)$-Bernstein condition, then
    $X$ satisfies $\qty(D',s')$-Bernstein condition for any 
    $D' \ge D$ and $s' \ge s$.
    Similarly, if $X$ satisfies one-sided $\qty(D,s)$-Bernstein condition, then
    $X$ satisfies one-sided $\qty(D',s')$-Bernstein condition for any 
    $D' \ge D$ and $s' \ge s$.
    \item \label{item:Bernstein condition 2}
    If $X$ satisfies $\qty(D,s)$-Bernstein condition, then $aX$ satisfies $(\abs{a}D,a^2s)$-Bernstein condition for any $a \in \mathbb{R}$.
    If $X$ satisfies one-sided $\qty(D,s)$-Bernstein condition, then $aX$ satisfies one-sided $(a D,a^2s)$-Bernstein condition for any $a \geq 0$.
    \item \label{item:dominated Bernstein condition}
    If $X$ satisfies one-sided $\qty(D,s)$-Bernstein condition and $Y\preceq X$, 
    then $Y$ satisfies one-sided $\qty(D, s)$-Bernstein condition, where $\preceq$ denotes the stochastic domination (see \cref{def:Stochastic domination}).
    In particular,
      if $X$ satisfies one-sided $\qty(D,s)$-Bernstein condition and $Y\leq  X$,  
      then $Y$ satisfies one-sided $\qty(D, s)$-Bernstein condition.
    \item \label{item:BC for independent rvs} 
    If a sequence of $n$ random variables $X_1,\ldots,X_n$ are independent and $X_i$ satisfies $\qty(D,s_i)$-Bernstein condition for $i\in [n]$, 
    then $\sum_{i\in [n]}X_i$ satisfies $\qty(D,\sum_{i\in [n]}s_i)$-Bernstein condition. 
    \item \label{item:BC for NA rvs} 
    If a sequence of $n$ random variables $X_1,\ldots,X_n$ are negatively associated and $X_i$ satisfies one-sided $\qty(D,s_i)$-Bernstein condition for $i\in [n]$, 
    then $\sum_{i\in [n]}X_i$ satisfies one-sided $\qty(D,\sum_{i\in [n]}s_i)$-Bernstein condition. 
\end{enumerate}

For the first claim, consider $\lambda\in \mathbb{R}$ such that $\abs{\lambda} D'<3$.
For such $\lambda$, we also have $\abs{\lambda} D \leq \abs{\lambda} D'<3$.
Since $X$ satisfies $(D,s)$-Bernstein condition, 
    \begin{align*}
        \mathbb{E}\sbra*{\mathrm{e}^{\lambda X}}
        \leq \exp\rbra*{\frac{\lambda^2s/2}{1-(\abs{\lambda}D )/3}}
        \leq \exp\rbra*{\frac{\lambda^2s'/2}{1-(\abs{\lambda}D' )/3}}
    \end{align*}
    holds, and we obtain the first claim.
    Similarly, for the second claim, consider $\lambda \geq 0$ such that $\lambda D'<3$.
    For such $\lambda$, we also have $\lambda D \leq \lambda D'<3$.
    Since $X$ satisfies one-sided $(D,s)$-Bernstein condition,

    \begin{align*}
        \mathbb{E}\sbra*{\mathrm{e}^{\lambda X}}
        \leq \exp\rbra*{\frac{\lambda^2s/2}{1-(\lambda D )/3}}
        \leq \exp\rbra*{\frac{\lambda^2s'/2}{1-(\lambda D' )/3}}
    \end{align*}
    holds, and we obtain the second claim.

For the first claim, consider $\lambda\in \mathbb{R}$ such that $\abs{\lambda} \qty(\abs{a} D)<3$.
For such $\lambda$, we also have $\abs{\lambda a} D \leq \abs{\lambda} \abs{a} D<3$.
Since $X$ satisfies $(D,s)$-Bernstein condition, we have
    \begin{align*}
        \mathbb{E}\sbra*{\mathrm{e}^{\lambda (aX)}}
        =\mathbb{E}\sbra*{\mathrm{e}^{(\lambda a)X}}
        \leq \exp\rbra*{\frac{(\lambda a)^2s/2}{1-(\abs{\lambda a}D )/3}}
        \leq \exp\rbra*{\frac{\lambda^2 (a^2s)/2}{1-(\abs{\lambda} (\abs{a}D) )/3}}
    \end{align*}
and we obtain the first claim.

For the second claim, consider $\lambda\geq 0$ such that $\lambda \qty(a D)<3$.

Since $X$ satisfies one-sided $(D,s)$-Bernstein condition, we have
    \begin{align*}
        \mathbb{E}\sbra*{\mathrm{e}^{\lambda (aX)}}
        =\mathbb{E}\sbra*{\mathrm{e}^{(\lambda a)X}}
        \leq \exp\rbra*{\frac{(\lambda a)^2s/2}{1-(\lambda aD )/3}}
        = \exp\rbra*{\frac{\lambda^2 (a^2s)/2}{1-(\lambda a D )/3}}
    \end{align*}
and we obtain the second claim.

Consider $\lambda \geq 0$ such that $\lambda D <3$.
Then, $f(x) = \mathrm{e}^{\lambda x}$ is non-decreasing and hence $\mathbb{E}[\mathrm{e}^{\lambda X}]\leq \mathbb{E}[\mathrm{e}^{\lambda Y}]$ holds for random variables such that $X\preceq Y$ (see \cref{lem:Stochastic domination}).
Hence, 

    \begin{align*}
        \mathbb{E}\sbra*{\mathrm{e}^{\lambda Y}}
        \leq \mathbb{E}\sbra*{\mathrm{e}^{\lambda X}}

        \leq \exp\rbra*{\frac{\lambda^2s/2}{1-(\lambda D )/3}}
    \end{align*}
    holds and we obtain the claim.

  In particular, if $Y\leq X$, then $Y\preceq X$ (see \cref{lem:Stochastic domination}), which proves the claim.

Since \cref{item:C1} implies $\mathbf{1}_{\tau>t-1}\rbra*{X_t-X_{t-1}-R}\leq \mathbf{1}_{\tau>t-1}\rbra*{X_t-\mathbb{E}_{t-1}[X_t]}$, we can use the following \cref{item:C2'} instead of \cref{item:C2}:
