\label{thm:general Freedman}
    Let $(X_t)_{t\in \mathbb{N}_0}$ be a real-valued supermartingale associated with the natural filtration $(\mathcal{F}_t)_{t\in \mathbb{N}_0}$.
    Assume that $V_{t-1}$, $t\in [T]$ are positive and $\mathcal{F}_{t-1}$-measurable random variables.
    Suppose 
    $
    \mathbb{E}_{t-1}\sbra*{\exp\rbra*{\lambda (X_t-X_{t-1})}}\leq \exp\rbra*{f(\lambda)V_{t-1}}
    $
    for all $t\in [T]$ and for a positive function $f(\lambda)$ for some $\lambda\in (0,\infty)$.
    Then, for all $h, W>0$,
    \begin{align*}
        \Pr\sbra*{{}^{\exists} t \le T,\,X_t-X_0\geq h \textrm{ and }\sum_{i=1}^tV_{i-1}\leq W} \leq \exp\rbra*{-\lambda h+f(\lambda)W }.
    \end{align*}

\begin{align*}
            \Pr\sbra*{{}^{\exists} t \le T,\,X_t-X_0\geq h \textrm{ and }\sum_{i=1}^tV_{i-1}\leq W} \leq \exp\rbra*{-\lambda h+f(\lambda)W }.
        \end{align*}


\label{cor:Freedman}
  Let $(X_t)_{t\in \mathbb{N}_0}$ be a supermartingale associated with the natural filtration $(\mathcal{F}_t)_{t\in \mathbb{N}_0}$.
  Suppose that, for every $t\ge 1$, the difference $X_t - X_{t-1}$ conditioned on $\mathcal{F}_{t-1}$ satisfies one-sided $(D,s)$-Bernstein condition.
  Then, for any $h > 0$, we have
\begin{align*}
   \Pr\sbra*{{}^{\exists} t\le T,\,X_t-X_0\geq h} \leq \exp\rbra*{-\frac{h^2/2}{Ts + (hD )/3}}.
\end{align*}

\begin{align*}
        \Pr\sbra*{{}^{\exists}t\le T,\,Y_t-Y_0\geq h}
        &=\Pr\sbra*{{}^{\exists}t\le T,\,Y_t-Y_0\geq h \text{ and }\sum_{i=1}^t V_{i-1}\leq s T}\\
        &\leq \exp\rbra*{-\lambda h+\frac{\lambda^2/2}{1-(\lambda D/3)}\cdot Ts }\\
        &=\exp\rbra*{-\frac{h^2/2}{Ts+(hD)/3}}.
      \end{align*}

For the parameter $z>0$ (either $ z=h-R\cdot T $ or $ z = (-R)\cdot T - h $), consider the following stopping time:
\begin{align*} 
   \tau_X\mathrel{\mathop:}= \inf\cbra*{t\geq 0\colon X_t\geq X_0+R\cdot t+z}.
\end{align*}
  Let $Y_t=X_t-R\cdot t$ and $Z_t=Y_{t\wedge \tau}$.
  Then, $Z_t-Z_{t-1}$ conditioned on $\mathcal{F}_{t-1}$ satisfies one-sided $\qty(D,s)$-Bernstein condition and
  $(Z_t)_{t\in \mathbb{N}_0}$ is a supermartingale since
  \begin{align*}
  Z_t-Z_{t-1}
  =\mathbf{1}_{\tau>t-1}\rbra*{Y_t-Y_{t-1}}
  =\mathbf{1}_{\tau>t-1}\rbra*{X_t-X_{t-1}-R}
  \end{align*}
  and
  \begin{align*}
    \mathbb{E}_{t-1}\sbra*{Z_t-Z_{t-1}}
    =\mathbf{1}_{\tau>t-1}\rbra*{\mathbb{E}_{t-1}[X_t]-X_{t-1}-R}
    \leq 0.
  \end{align*}
  Then, 

  we obtain
  \begin{align*}
    \Pr\qty[\tau_X \le \min\{T,\tau\}] 
    &=\Pr\qty[{}^{\exists} t\le T\land \tau,\,X_t\geq X_0+R\cdot t+z ] \\
    &=\Pr\qty[{}^{\exists} t \le T \land \tau,\,Y_t\geq Y_0+z] &&(\because Y_t=X_t-Rt)\\
    &=\Pr\qty[{}^{\exists} t \le T\land \tau,\,Z_t\geq Z_0+z] &&(\because t\leq T\wedge \tau \leq \tau)\\
    &\le \Pr\qty[{}^{\exists} t \le T,\,Z_t\geq Z_0+z]\\
    &\le \exp\qty(- \frac{z^2/2}{s T + (z D)/3}) &&(\because \textrm{\cref{cor:Freedman}}).
  \end{align*}
  For the first claim, it suffices to show that $\Pr[\tau_X^+ \le \min\{T,\tau\}] 
  \leq \Pr\qty[\tau_X \le \min\{T,\tau\}]$.
  Since $D\geq 0$ and $R T\leq h-z$, we have
  \begin{align*}
    \Pr\qty[\tau_X^+ \le \min\{T,\tau\}] 
    &=\Pr\qty[{}^{\exists} t \le T,\,X_t\geq X_0+h]\\

    &\leq \Pr\qty[{}^{\exists} t \le T\land \tau,\,X_t\geq X_0+R\cdot t+z]&&(\because h\geq R\cdot T+z\geq R\cdot t+z)\\
    &=\Pr\qty[\tau_X \le \min\{T,\tau\}].
  \end{align*}

Now, we apply \cref{thm:general Freedman} for $\lambda=\frac{h}{Ts+(hD )/3} > 0$, 
  $f(\lambda)=\frac{\lambda^2/2}{1-(\lambda D /3)}$, $W=T s$, and $V_t = s$ (for all $t$).
  Due to the one-sided Bernstein condition of $Y_t - Y_{t-1}$, we have $\mathbb{E}_{t-1}\qty[ \exp\qty( \lambda (Y_t - Y_{t-1}) ) ] \le \exp\qty( f(\lambda) V_{t-1} )$.
  Note that $\lambda D =\frac{h D}{Ts+(h D)/3}<3$.
  Therefore, from \cref{thm:general Freedman}, we obtain
  \begin{align*}
    \Pr\sbra*{{}^{\exists}t\le T,\,Y_t-Y_0\geq h}
    &=\Pr\sbra*{{}^{\exists}t\le T,\,Y_t-Y_0\geq h \text{ and }\sum_{i=1}^t V_{i-1}\leq s T}\\
    &\leq \exp\rbra*{-\lambda h+\frac{\lambda^2/2}{1-(\lambda D/3)}\cdot Ts }\\
    &=\exp\rbra*{-\frac{h^2/2}{Ts+(hD)/3}}.
  \end{align*}

  For the second claim, it suffices to show that $\Pr[\min\{\tau_X^-,\tau\} >T] 
    \leq \Pr\qty[\tau_X \le \min\{T,\tau\}]$.
  Since $R < 0$ (i.e., $-R>0$) and $-R T\geq h+z$, we have
