    &\leq \Pr\qty[X_T> X_0+R\cdot T+z\textrm{ and }\tau>T] &&(\because -h\geq R\cdot T+z)\\
    &=\Pr\qty[X_{T\wedge \tau}> X_0+R\cdot (T\wedge \tau)+z\textrm{ and }\tau>T] \\
    &\leq \Pr\qty[X_{T\wedge \tau}\geq  X_0+R\cdot (T\wedge \tau)+z] \\
    &\leq \Pr\qty[{}^{\exists} t \le T \land \tau,\,X_t\geq X_0+R\cdot t+z ]\\
    &=\Pr\qty[\tau_X \le \min\{T,\tau\}].
  \end{align*}

\begin{align*}
        \Pr\qty[\tau_X^+ \le \min\{T,\tau\}] 
        &=\Pr\qty[{}^{\exists} t \le T,\,X_t\geq X_0+h]\\

        &\leq \Pr\qty[{}^{\exists} t \le T\land \tau,\,X_t\geq X_0+R\cdot t+z]&&(\because h\geq R\cdot T+z\geq R\cdot t+z)\\
        &=\Pr\qty[\tau_X \le \min\{T,\tau\}].
      \end{align*}

