\label{lem:basic inequality}
  Consider the quantities defined in \cref{def:basic quantities} for 3-Majority or 2-Choices.
  Then, we have the following for any $t\geq 1$:
\begin{enumerate}

\item \label{item:alpha} 
For any opinion $i \in [k]$, we have
  \begin{align*} 
     &\mathbb{E}_{t-1} [\alpha_t(i)] = 
      \alpha_{t-1}(i) \qty( 1 + \alpha_{t-1}(i) - \gamma_{t-1} ), \\ 
    &\mathbf{Var}_{t-1}[\alpha_t(i)] \le \begin{cases}
      \frac{\alpha_{t-1}(i)}{n}	& \text{for 3-Majority},\\
      \frac{\alpha_{t-1}(i)(\alpha_{t-1}(i) + \gamma_{t-1})}{n}	& \text{for 2-Choices}.
    \end{cases} 
  \end{align*}
\item \label{item:delta} 
For any two distinct opinions $i,j\in [k]$, we have
  \begin{align*} 
     &\mathbb{E}_{t-1} [\delta_t(i,j)] =
      \delta_{t-1}(i,j) \qty( 1 + \alpha_{t-1}(i) + \alpha_{t-1}(j) - \gamma_{t-1} ), \\

    &\mathbf{Var}_{t-1}[\delta_t(i,j)] \le \begin{cases}
      \frac{2}{n}(\alpha_{t-1}(i) + \alpha_{t-1}(j))	& \text{for 3-Majority},\\[10pt]
      \frac{1}{n}(\alpha_{t-1}(i)+\alpha_{t-1}(j))(\alpha_{t-1}(i)+\alpha_{t-1}(j)+\gamma_{t-1})	& \text{for 2-Choices}.
    \end{cases} 
  \end{align*}
\item \label{item:expectation of alphanorm} 
It holds that
\begin{align*} 
\mathbb{E}_{t-1}[\gamma_{t}] \ge \begin{cases}
   \gamma_{t-1}+\frac{1-\gamma_{t-1}}{n}	& \text{for 3-Majority},\\[10pt]
   \gamma_{t-1}+\frac{(1-\sqrt{\gamma_{t-1}})(1-\gamma_{t-1})\gamma_{t-1}}{n}	& \text{for 2-Choices}.
 \end{cases} 
\end{align*}
In particular, $\mathbb{E}_{t-1}[\gamma_{t}] \geq \gamma_{t-1}$.
\end{enumerate}

\label{lem:Bernstein condition for sync processes}
Consider the quantities defined in \cref{def:basic quantities} for 3-Majority or 2-Choices.
Then, we have the following for any $t\geq 1$:
\begin{enumerate}

    \item \label{item:BC for alpha}
    For any opinion $i\in [k]$, 
    $\alpha_{t}(i)-\mathbb{E}_{t-1}\sbra*{\alpha_t(i)}$ conditioned on round $t-1$ satisfies $\qty(\frac{1}{n},s)$-Bernstein condition, where
    \begin{align*} 
       s = \begin{cases}
        \frac{\alpha_{t-1}(i)}{n}	& \text{for 3-Majority},\\
        \frac{\alpha_{t-1}(i)(\alpha_{t-1}(i)+\gamma_{t-1})}{n} & \text{for 2-Choices}.
       \end{cases}
    \end{align*}
    \item \label{item:BC for delta}
     For any two distinct opinions $i,j\in [k]$,
     $\delta_{t}(i,j)-\mathbb{E}_{t-1}\sbra*{\delta_t(i,j)}$ conditioned on round $t-1$ satisfies $ \qty(\frac{2}{n}, s) $-Bernstein condition, 
     where
    \begin{align*} 
       s = \begin{cases}
          \frac{2}{n}(\alpha_{t-1}(i)+\alpha_{t-1}(j))	& \text{for 3-Majority},\\[10pt]
          \frac{1}{n}\qty(\alpha_{t-1}(i) + \alpha_{t-1}(j))\qty(\alpha_{t-1}(i)+\alpha_{t-1}(j)+\gamma_{t-1}) & \text{for 2-Choices}.
       \end{cases} 
    \end{align*}
    \item \label{item:BC for alphanorm}
     $\gamma_{t-1}-\gamma_t$ conditioned on round $t-1$ satisfies one-sided $ \qty(\frac{2\sqrt{\gamma_{t-1}}}{n},s)$-Bernstein condition, where
    \begin{align*}
       s = \begin{cases}
          \frac{4}{n}\gamma_{t-1}^{1.5}	& \text{for 3-Majority},\\[10pt]
          \frac{8}{n}\gamma_{t-1}^2 & \text{for 2-Choices}.
       \end{cases}
    \end{align*} 
\end{enumerate}

 \label{def:stopping times}
  Consider the quantities defined in \cref{def:basic quantities} for 3-Majority or 2-Choices.
  Fix two distinct opinions $i,j\in [k]$.
\begin{enumerate}

  \item  For constants $c_\alpha^{\uparrow},c_\alpha^{\downarrow}>0$, define
    \begin{align*}
        &\tau^{\uparrow}_i = \inf\cbra*{ t \ge 0 \colon \alpha_t(i) \ge (1+c_\alpha^{\uparrow})\alpha_0(i)},\\
        &\tau^{\downarrow}_i = \inf\cbra*{ t \ge 0 \colon \alpha_t(i) \le (1-c_\alpha^{\downarrow})\alpha_0(i)}.
    \end{align*}

  \item For constants $ c^{\uparrow}_\delta,c^{\downarrow}_\delta >0$ and a parameter $ x_{\delta} = x_{\delta}(n) \in [1/n, 1]$, define
    \begin{align*}
        &\tau^{\uparrow}_\delta = \inf\cbra*{ t \ge 0 \colon \delta_t(i,j) \ge (1+c^{\uparrow}_\delta) \delta_0(i,j) },\\
        &\tau^{\downarrow}_\delta = \inf\cbra*{ t \ge 0 \colon \delta_t(i,j) \le (1-c^{\downarrow}_\delta) \delta_0(i,j) }, \\
        &\tau^{+}_\delta= \inf\qty{t\geq 0: \abs{\delta_t(i,j)}\geq x_{\delta}}.
    \end{align*}

  \item For constants $c^{\uparrow}_\gamma,c^{\downarrow}_\gamma>0$ and a parameter $x_{\gamma} = x_{\gamma}(n)\in[0,1]$, define
    \begin{align*}
        &\tau^{\uparrow}_\gamma = \inf\{t\geq 0: \gamma_t\geq (1+c^{\uparrow}_\gamma)\gamma_0\}, \\
        &\tau^{\downarrow}_\gamma = \inf\cbra*{t\geq 0: \gamma_t\leq (1-c^{\downarrow}_\gamma)\gamma_0}, \\
        &\tau^{+}_{\gamma} \mathrel{\mathop:}= \inf\qty{t\geq 0: \gamma_t\geq x_{\gamma}}. 
    \end{align*}

  \item For a constant $0\le c^{\mathrm{weak}}<1/2$, we say that an opinion $i\in[k]$ is \emph{weak at round $t$} if $\alpha_t(i) \le (1-c^{\mathrm{weak}}) \gamma_t$.
    We define
    \begin{align*} 
        &\tau^{\mathrm{weak}}_i = \inf\cbra*{ t \ge 0 \colon \alpha_t(i) \le (1-c^{\mathrm{weak}}) \gamma_t }.
    \end{align*}
  \item  For a constant $c^{\mathrm{active}}>0$ satisfying $c^{\downarrow}_\gamma<c^{\mathrm{active}}<c^{\mathrm{weak}}$, we say that an opinion $ i \in [k]$ is \emph{active at round $ t $} if $ \alpha_t(i) \ge (1-c^{\mathrm{active}})\cdot \gamma_0$.
  We define
  \begin{align*} 
    \tau^{\mathrm{active}}_i = \inf\qty{ t \ge 0 \colon \alpha_t(i) \ge (1-c^{\mathrm{active}})\cdot \gamma_0 } .
  \end{align*}
\end{enumerate}

  The constants $c_\alpha^{\uparrow},c_\alpha^{\downarrow},c^{\uparrow}_\delta,c^{\downarrow}_\delta,c^{\uparrow}_\gamma,c^{\downarrow}_\gamma,c^{\mathrm{weak}},c^{\mathrm{active}}$ are universal constants, e.g., 
  we can set $c^{\uparrow}_\alpha=c^{\downarrow}_\alpha=c^{\mathrm{weak}}=1/10$, $c^{\uparrow}_\delta=c^{\downarrow}_\delta=c^{\mathrm{active}}=1/20$, and $c^{\uparrow}_\gamma=c^{\downarrow}_\gamma=1/30$ for both 3-Majority and 2-Choices.

  \label{lem:drift analysis for basic}
  Consider stopping times defined in \cref{def:stopping times}.
  Fix two distinct opinions $i,j\in [k]$.
  Then, we have the following:
  \begin{enumerate}

\item \label{item:tauiup}
For any constant $\varepsilon\in (0,1)$, 
let $C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauiup})}}\mathrel{\mathop:}= \frac{ (1 - \varepsilon) c_\alpha^{\uparrow} }{(1+c_\alpha^{\uparrow})^2}$.
Then, we have
\begin{align*}
\Pr\qty[ \tau^{\uparrow}_i \le \frac{C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauiup})}}}{ \alpha_0(i)} ] \le 
    \begin{cases}
        \exp\qty(-\Omega\qty( n\alpha_0(i)^2 ))	& \text{for 3-Majority},\\[10pt]
        \exp\qty( -\Omega\qty( n\alpha_0(i) ) ) & \text{for 2-Choices}.
    \end{cases}
\end{align*}
\item \label{item:tauidown}
For any constant $\varepsilon \in (0,1)$, let
$C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauidown})}}\mathrel{\mathop:}= \frac{(1-c^{\mathrm{weak}})(1-\varepsilon)c^{\downarrow}_\alpha}{c^{\mathrm{weak}} (1+c_\alpha^{\uparrow})^2}$.
Then, we have
\begin{align*}
