\label{lem:taunormdown is large}
  Consider the stopping times $\tau^{\uparrow}_\gamma,\tau^{\downarrow}_\gamma$ defined in \cref{def:stopping times}.
  Then, for any $T>0$, we have
    \begin{align*}
        \Pr\qty[\tau^{\downarrow}_\gamma\leq T]\le
          \begin{cases}
          T\cdot \exp\qty(-\Omega\qty(\frac{n\sqrt{\gamma_0}}{T})) & \text{for 3-Majority}, \\[10pt]
          T\cdot \exp\qty(-\Omega\qty(\frac{n}{T+\gamma_0^{-1/2}})) & \text{for 2-Choices}.
        \end{cases}
    \end{align*}
  Specifically, we have the following for a sufficiently large constant $C>0$:
  Suppose that $\gamma_0\geq \frac{C\log n}{\sqrt{n}}$ for 3-Majority and $\gamma_0\geq \frac{(C\log n)^2}{n}$ for 2-Choices. Then, $\Pr\qty[\tau^{\downarrow}_\gamma\leq \frac{C\log n}{\gamma_0}]\leq O(n^{-10})$.

For simplicity, we prove the claim for 3-Majority.
The same proof works for 2-Choices.
  For each $0\le s \le T$,
  let $\sigma^{\downarrow}_s = \inf\{ t\ge s \colon \gamma_t \le (1-c^{\downarrow}_\gamma) \gamma_s \}$,
  $\sigma^{\uparrow}_s = \inf\{t \ge s \colon \gamma_t \ge 2\gamma_s\}$,
  and
  let $\mathcal{E}^{(s)}$ be the event that $\gamma_s \ge \gamma_0$ and $\sigma^{\downarrow}_s \le \min\{T, \sigma^{\uparrow}_s\}$.
  Note that $\tau^{\downarrow}_\gamma = \sigma^{\downarrow}_0$ and $\tau^{\uparrow}_\gamma = \sigma^{\uparrow}_0$ (for $c^{\uparrow}_\gamma=1$).

  The key observation is that the partial process $(\alpha_t)_{t\ge s}$ is again a 3-Majority process and $\sigma_t^{\uparrow},\sigma_t^{\downarrow}$ can be seen as the stopping times of \cref{def:stopping times} for the partial process.
  Moreover, the event $\mathcal{E}^{(s)}$ depends only on the partial process $(\alpha_t)_{t\ge s}$.
  Therefore, from \cref{item:taunormdown} of \cref{lem:drift analysis for basic}, we have
  \begin{align*}
      \Pr_{(\alpha_t)_{t\ge s}}\qty[ \mathcal{E}^{(s)} ] &\le \Pr_{(\alpha_t)_{t\ge s}}\qty[ \sigma_s^{\downarrow} \le \min\{T, \sigma^{\uparrow}_s\} \middle| \gamma_s \ge \gamma_0 ] \\
      &\le \exp\qty( - \Omega\qty( \frac{n\sqrt{\gamma_0}}{T})).
  \end{align*}

  If $\tau^{\downarrow}_\gamma \le T$ occurs, then $\mathcal{E}^{(s)}$ occurs for some $0\le s \le T$.
  For example, if $s\le \tau^{\downarrow}_\gamma$ is the round such that $\gamma_s = \max_{0\le t \le \tau^{\downarrow}_\gamma} \gamma_t$, then $\mathcal{E}^{(s)}$ holds.
  Therefore, we have
  \begin{align*}
      \Pr\qty[ \tau^{\downarrow}_\gamma \le T ] &\le \Pr\qty[ \bigvee_{0\le s \le T} \mathcal{E}^{(s)} ] \\
      &\le \sum_{0\le s \le T} \Pr\qty[ \mathcal{E}^{(s)}] \\
      &\le T\exp\qty( - \Omega\qty( \frac{n\sqrt{\gamma_0}}{T} )).
  \end{align*}    

  Now, we prove the ``specifically'' part.
  For 3-Majority, substituting $T=\frac{C\log n}{\gamma_0}$ yields the claim since
  \begin{align*}
  \frac{n\sqrt{\gamma_0}}{T}
  =\frac{n\gamma_0^{1.5}}{C\log n}
  \geq  n^{1/4}\sqrt{C \log n}.
  \end{align*}


  For 2-Choices, substituting  $T=\frac{C\log n}{\gamma_0}$ yields the claim since
  \begin{align*}
  \frac{n}{T+\gamma_0^{-1/2}}
  = \frac{n}{\frac{C\log n}{\gamma_0}+\frac{1}{\sqrt{\gamma_0}}}
  \geq \frac{n}{\frac{n}{C\log n}+\frac{\sqrt{n}}{C\log n}}
  \geq \frac{C\log n}{2}.
  \end{align*}

\begin{align*}
        \Pr\qty[ \tau^{\downarrow}_\gamma \le T ] &\le \Pr\qty[ \bigvee_{0\le s \le T} \mathcal{E}^{(s)} ] \\
        &\le \sum_{0\le s \le T} \Pr\qty[ \mathcal{E}^{(s)}] \\
        &\le T\exp\qty( - \Omega\qty( \frac{n\sqrt{\gamma_0}}{T} )).
    \end{align*}

\label{def:tauivanish}
 For an opinion $ i $, define $ \tau^{\mathrm{vanish}}_i $ as the first time when $ i $ vanishes, i.e.,
 \begin{align*} 
    \tau^{\mathrm{vanish}}_i = \inf\qty{ t \ge 0 \colon \alpha_t(i) = 0 }.
 \end{align*}

\label{lem:weakvanish}
  Consider the stopping time $ \tau^{\mathrm{vanish}}_i $ defined in \cref{def:tauivanish}.

  Let $ i $ be an arbitrary weak opinion. 
  Suppose that, in 3-Majority, $ \gamma_0 \ge \frac{C\log n}{\sqrt{n}} $ and in 2-Choices, $ \gamma_0 \ge \frac{C(\log n)^2}{n} $, where $C>0$ is a sufficiently large constant. 
  Then, we have






  \begin{align*} 
     \Pr\qty[ \tau^{\mathrm{vanish}}_i \le \frac{C\log n}{\gamma_0} ] = 1-O(n^{-10}).
  \end{align*}

Let $ \tau = \min\{\tau^{\mathrm{active}}_i,\tau^{\downarrow}_\gamma,\tau^{\mathrm{vanish}}_i\} $ and 
  $r = 1 - (c^{\mathrm{active}} - c^{\downarrow}_\gamma)\gamma_0$.
  Note that $1>c^{\mathrm{active}} > c^{\downarrow}_\gamma>0$ from \cref{def:stopping times}.

  Suppose $t-1 < \tau$.
  For both models, we have
  \begin{align*} 
    \mathbb{E}_{t-1}\sbra*{ \alpha_t(i) } &= \alpha_{t-1}(i)(1+\alpha_{t-1}(i) - \gamma_{t-1}) \\
    &\le \alpha_{t-1}(i)(1+(1-c^{\mathrm{active}})\gamma_0 - (1-c^{\downarrow}_\gamma)\gamma_0) \\
    &= r\alpha_{t-1}(i).
  \end{align*}

  Let $ X_t = r^{-t}\cdot \alpha_{t}(i) $
  and $ Y_t = X_{t\land \tau}$.
  Then, $(Y_t)$ is a supermartingale for both models since
  \begin{align*} 
     \mathbb{E}_{t-1}\qty[ Y_t - Y_{t-1} ] &=\mathbf{1}_{t-1<\tau}\cdot \mathbb{E}_{t-1}\qty[ X_t - X_{t-1} ] =\mathbf{1}_{t-1<\tau}r^{-t}\qty(\mathbb{E}_{t-1}\qty[ \alpha_t(i) ] - r\alpha_{t-1}(i)) \le 0.
  \end{align*}
  Furthermore, for any $T\ge 0$,
  \begin{align*}
    \mathbb{E}\sbra*{Y_T}
    &\geq \mathbb{E}\sbra*{Y_T\mid \tau>T}\Pr\sbra*{\tau>T}\\
    &=\mathbb{E}\sbra*{X_T\mid \tau>T}\Pr\sbra*{\tau>T} & & \because\text{$X_T=Y_T$ if $\tau>T$} \\
    &=r^{-T}\mathbb{E}\sbra*{\alpha_T(i)\mid \tau>T}\Pr\sbra*{\tau>T}\\
    &\geq r^{-T}n^{-1}\Pr\sbra*{\tau>T}. & & \because\text{$\alpha_T(i) \ge 1/n$ if $T>\tau^*_i$}
  \end{align*}
  and, since $ (Y_t) $ is a supermartingale, we obtain
  \begin{align}
    \Pr\sbra*{\tau>T}
    &\leq nr^T\mathbb{E}\sbra*{Y_T} \nonumber \\
    &\leq nr^T\mathbb{E}\sbra*{Y_0} \nonumber \\
    &\leq 
      n\exp\rbra*{-(c^{\mathrm{active}}-c^{\downarrow}_\gamma)\gamma_0T}. \label{eq:weak multi}
    \end{align}


  From \cref{lem:taunormdown is large} and \cref{item:tauiactive} of \cref{lem:drift analysis for basic} for $ T=\frac{C\log n}{\gamma_0}$ for a sufficiently large constant $C$, we have
  \begin{align} 
    \Pr[\tau^{\downarrow}_\gamma \le T] &\le 
     \begin{cases}
      T\exp\qty(-\Omega\qty(\frac{n\gamma_0^{1.5}}{\log n}))	& \text{for 3-Majority},\\[10pt]
      T\exp\qty(-\Omega\qty( \frac{n\gamma_0}{\log n} )) & \text{for 2-Choices}.
     \end{cases} \nonumber\\
     &\le n^{-10} \label{eq:taunormdown bound}
  \end{align}
  and
  \begin{align*}
    \Pr\qty[\tau^{\mathrm{active}}_i\leq \min\{T,\tau^{\downarrow}_\gamma\}]
      &\leq 
      \begin{cases}
          \exp\qty(-\Omega\qty(\frac{n\gamma_0^2}{\log n})) & \text{for 3-Majority}, \\[10pt]
          \exp\qty(-\Omega\qty(\frac{n\gamma_0}{\log n})) & \text{for 2-Choices}.\\
      \end{cases} \\
      &\le n^{-10}.
  \end{align*}
  Here, we used the assumption of $ \gamma_0 $.
  Thus, we have
  \begin{align} 
     \Pr\qty[ \tau^{\mathrm{active}}_i \le T ] &= \Pr\qty[ \tau^{\mathrm{active}}_i\le T \text{ and }\tau^{\mathrm{active}}_i \le \tau^{\downarrow}_\gamma ] + \Pr\qty[ \tau^{\mathrm{active}}_i\le T \text{ and }\tau^{\mathrm{active}}_i > \tau^{\downarrow}_\gamma ]  \nonumber\\
