\label{def:tauetaup}
 Consider 2-Choices and let $ i,j $ be distinct opinions.
 Let
 \begin{align*} 
   \eta_t(i,j) = \frac{\delta_t(i,j)}{\sqrt{\max\qty{\alpha_t(i),\alpha_t(j)}}}.
 \end{align*}
 For a constant $c^\uparrow_\eta>0$ and a parameter $ x_{\eta}=x_{\eta}(n)\in[1/n,1] $, let
 \begin{align*} 
   &\tau^{\uparrow}_\eta = \inf\qty{ t\ge 0 \colon \eta_t(i,j) \ge (1+c^\uparrow_\eta)\eta_0 }, \\
   &\tau^{+}_\eta = \inf\qty{t\geq 0: \abs{\eta_t(i,j)}\geq x_{\eta}}.
 \end{align*}  
 The constant $c^\uparrow_\eta$ is a universal constant and we will set $c^\uparrow_\eta=1/1000$.

\label{lem:deltaupweak}
  Let $ i,j $ be distinct opinions that are not weak at round $ 0 $ and $ \alpha_0(i) \ge \alpha_0(j) $.
  Consider the stopping times $\tau^{\mathrm{weak}}_j,\tau^{\uparrow}_\delta, \tau^{\uparrow}_\eta$ defined in \cref{def:tauetaup,def:stopping times}
  and let $c^{\mathrm{weak}}=1/10, c^{\uparrow}_\delta=1/20, c^\uparrow_\eta=1/1000$.
  Then, we have the following:
\begin{enumerate}

