     \Pr\qty[ \min\qty{ \tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j } >  \frac{1}{\gamma_0} ] \le \exp\qty(-\Omega\qty(n\gamma_0^2)) + \exp\qty(-\Omega\qty(n\delta_0(i,j)^2)). 
  \end{align*}
  \item For 2-Choices,
  \begin{align*} 
    \Pr\qty[ \min\qty{ \tau^{\uparrow}_\eta,\tau^{\mathrm{weak}}_j } >  \frac{1}{\gamma_0} ] \le  \exp\qty(-\Omega\qty(n\gamma_0)) + \exp\qty(-\Omega\qty( n\eta_0(i,j)^2 )).
  \end{align*}
\end{enumerate}

Let
\begin{align*} 
   P &= \begin{cases}
    \exp\qty(-\Omega\qty(n\alpha_0(i)^2)) & \text{for 3-Majority},\\
    \exp\qty(-\Omega\qty(n\alpha_0(i)))   & \text{for 2-Choices},
   \end{cases}\\
   Q &= \begin{cases}
    \exp\qty( -\Omega(n\delta_0^2) )	& \text{for 3-Majority},\\
    \exp\qty( -\Omega\qty( n\eta_0^2)) & \text{for 2-Choices}.
   \end{cases}
\end{align*}
Set $c^{\uparrow}_\alpha=c^{\downarrow}_\alpha=c^{\mathrm{weak}}=\varepsilon=1/10$, and $c^{\uparrow}_\delta=c^{\downarrow}_\delta=1/20$.
Then, constants appearing in \cref{lem:drift analysis for basic} become
\begin{align*}
  C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauiup})}} &= \frac{ (1 - \varepsilon) c_\alpha^{\uparrow} }{(1+c_\alpha^{\uparrow})^2}=\frac{9}{121}>0.073,\\
  C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauidown})}} &= \frac{(1-c^{\mathrm{weak}})(1-\varepsilon)c^{\downarrow}_\alpha}{c^{\mathrm{weak}} (1+c_\alpha^{\uparrow})^2}=\frac{81}{121}>0.073,\\
  C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:taudeltaup})}} &= \frac{(1-c^{\mathrm{weak}})(1+\varepsilon)c^{\uparrow}_\delta}{(1-2c^{\mathrm{weak}})(1-c^{\downarrow}_\alpha)(1-c^{\downarrow}_\delta)}=\frac{11}{152}<0.073. 
\end{align*}

In other words, letting $T=\frac{0.073}{\alpha_0(i)}$, we have 
\begin{align*} 
    \frac{C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:taudeltaup})}}}{\alpha_0(i)} < T < \frac{\min\qty{C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauiup})}}, C_{\mbox{\tiny\ref{lem:drift analysis for basic}(\ref{item:tauidown})}}}}{\alpha_0(i)}.
\end{align*}
Note that we have $1/\gamma_0>T=0.073/\alpha_0(i)$ since $i$ is not weak at round $0$.

First, we present a partial proof that is common for both 3-Majority and 2-Choices.
Consider the stopping time
$ \tau_0 = \min\qty{ \tau^{\mathrm{weak}}_j,\tau^{\downarrow}_\delta,\tau^{\uparrow}_i,\tau^{\downarrow}_i, T } $.
Note that $ \tau_0 $ takes one of the values of $ \tau^{\mathrm{weak}}_j,\tau^{\downarrow}_\delta,\tau^{\uparrow}_i,\tau^{\downarrow}_i,T$.
The cases are divided based on which value it takes.
\begin{enumerate}
\item Suppose $ \tau_0 = \tau^{\uparrow}_i$, which implies $ \tau^{\uparrow}_i \le T $. From \cref{item:tauiup} of \cref{lem:drift analysis for basic}, this occurs with probability $P$. \label{item:multi tauiup}
\item Suppose $ \tau_0 = \tau^{\downarrow}_\delta$, which implies $ \tau^{\downarrow}_\delta \le \min\qty{ \tau^{\mathrm{weak}}_j, \tau^{\uparrow}_i, T }$. This occurs with probability $ Q $ from \cref{item:taudeltadown} of \cref{lem:drift analysis for basic}. \label{item:multi taudeltadown}
\item Suppose $ \tau_0 = \tau^{\downarrow}_i$, which implies $ \tau^{\downarrow}_i\le \min\qty{ \tau^{\downarrow}_\delta, \tau^{\mathrm{weak}}_j, T }$.
  Observe that, for any $ 0\le t < \min\qty{\tau^{\downarrow}_\delta,\tau^{\mathrm{weak}}_j} $, we have $ \alpha_t(i)\ge \alpha_t(j) $; thus, $ i $ cannot become weak during these rounds. Therefore, $ \tau^{\downarrow}_i\le \min\qty{ \tau^{\downarrow}_\delta, \tau^{\mathrm{weak}}_j, T } \le \min\qty{ \tau^{\downarrow}_\delta, \tau^{\mathrm{weak}}_i, T }  $.  This occurs with probability $ P $ from \cref{item:tauidown} of \cref{lem:drift analysis for basic}. 
  \label{item:multi tauidown}
\end{enumerate}
From above, we have
\begin{align} 
   \Pr\qty[ \tau_0 = \min\qty{\tau^{\mathrm{weak}}_j,T} ] \ge 1-2P-Q.  \label{eq:tau0 value}
\end{align}
Note that, since the opinion $ i $ is not weak at round $ 0 $, we can substitute $ \alpha_0(i)=\Omega(\gamma_0) $ to $ P $.

\begin{proof}[Proof for 3-Majority.]

From \cref{eq:tau0 value}, we have
\begin{align*}
&\Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j}>\frac{1}{\gamma_0}]\\
&\leq \Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j}>T] &&(\text{$\because$ $\alpha_0(i)\geq (1-c^{\mathrm{weak}})\gamma_0$})\\
&= \Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j,T}>T \textrm{ and } \tau_0=\min\qty{\tau^{\mathrm{weak}}_j,T}]\\
&\; + \Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j,T}>T \textrm{ and } \tau_0\neq \min\qty{\tau^{\mathrm{weak}}_j,T}]\\
&\leq \Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau_0}>T] + 2P+Q &&(\text{$\because$ \cref{eq:tau0 value}})\\
&\leq 2P+2Q. &&(\text{$\because$ \cref{item:taudeltaup} of \cref{lem:drift analysis for basic}})
\end{align*}
This proves the claim for 3-Majority.
\end{proof}



\begin{proof}[Proof for 2-Choices.]
The proof is similar to the proof for 3-Majority.
The key difference is to consider $ \tau^{\uparrow}_\eta $ in place of $ \tau^{\uparrow}_\delta $.
From \cref{eq:tau0 value}, we have
\begin{align*}
