&\; + \Pr\qty[\min\qty{\tau^{\uparrow}_\eta,\tau^{\mathrm{weak}}_j,T}>T \textrm{ and } \tau_0\neq \min\qty{\tau^{\mathrm{weak}}_j,T}]\\
&\leq \Pr\qty[\min\qty{\tau^{\uparrow}_\eta,\tau_0}>T] + 2P+Q. &&(\text{$\because$ \cref{eq:tau0 value}})\\
\end{align*}

Now, recall $c^{\uparrow}_\alpha=1/10,c^{\uparrow}_\delta=1/20$, and $c^\uparrow_\eta=1/1000$.
Then, we have $\frac{1+c^{\uparrow}_\delta}{\sqrt{1+c^{\uparrow}_\alpha}}=\frac{21\sqrt{110}}{220}>1+c^\uparrow_\eta$.
Noting $ \tau_0 = \min\qty{ \tau^{\mathrm{weak}}_j,\tau^{\downarrow}_\delta,\tau^{\uparrow}_i,\tau^{\downarrow}_i, T } $, 
we have
  \begin{align*}
      &\Pr\qty[\min\qty{\tau^{\uparrow}_\eta,\tau_0}>T]\\
      &=\Pr\qty[\min\qty{\tau^{\uparrow}_\eta,\tau_0}>T\textrm{ and }
      {}^{\forall} t\leq T, \frac{\delta_t}{\sqrt{\alpha_t(i)}}< (1+c^\uparrow_\eta)\frac{\delta_0}{\sqrt{\alpha_0(i)}}]&&(\because \tau^{\uparrow}_\eta>T)\\
      &=\Pr\qty[\min\qty{\tau^{\uparrow}_\eta,\tau_0}>T\textrm{ and }
      {}^{\forall} t\leq T, \delta_t< \underbrace{(1+c^\uparrow_\eta)\sqrt{1+c^{\uparrow}_\alpha}}_{\le 1+c^{\uparrow}_\delta}\delta_0] &&(\because \tau^{\uparrow}_i>T)\\

