      &\leq \Pr\qty[\min\qty{\tau^{\uparrow}_\delta,\tau_0}>T] \\
      &\le Q. & & (\because \text{\cref{item:taudeltaup} of \cref{lem:drift analysis for basic}})
  \end{align*}
  Combining the above, we obtain the claim for 2-Choices.
  \end{proof}

