 \label{lem:nazo lemma}
Let $ (Z_t)_{t\ge 0} $ be a Markov chain over a state space $ \Omega $ associated with natural filtration $\mathcal{F}=(\mathcal{F}_t)_{t\ge 0}$ and let $\tau$ be any stopping time with respect to $\mathcal{F}$.
Let $ \varphi \colon \Omega \to \mathbb{R}_{\ge 0} $ be a function.
For a parameter $ x\in\mathbb{R}_{\ge 0} $, let $ \tau_\varphi^+(x) = \inf\qty{t\ge 0 \colon \varphi(Z_t) \ge x} $.
Let $ T,x_0,c_\varphi^{\uparrow}>0 $ be parameters and suppose that the following holds:
\begin{enumerate}

\item There exists $ C_1>0 $ such that for any $ z \in \Omega $, \[ \Pr\qty[\min\qty{\tau_\varphi^+(x_0), \tau}\le T\;\middle\vert\; Z_0=z] \ge C_1. \] 
\item Define $ \tau^\uparrow_\varphi = \inf\qty{ t\ge 0 \colon \varphi(Z_t) \ge (1+c_\varphi^{\uparrow}) \cdot \varphi(Z_0) } $.
Then, there exists $ C_2>0$ such that for any $ z \in \Omega $, \[ \Pr\qty[ \min\qty{\tau^\uparrow_\varphi, \tau} \le T \;\middle\vert\; Z_0 = z ] \ge 1-\exp\qty( - C_2 \varphi(z)^2 ).\] 
\end{enumerate}
Then, there exists $ C = C(C_1,C_2,c_\varphi^{\uparrow},x_0) >0 $ such that,
for any $ x^* > x_0$, any $ z \in \Omega $ and any $ \varepsilon>0 $, we have
\begin{align*} 
  \Pr\qty[ \min\qty{\tau_\varphi^+(x^*), \tau} \le C\cdot T\cdot \qty(\log(1/\varepsilon) +  \log(x^*/x_0)) \;\middle\vert\; Z_0 = z] \ge 1-\varepsilon.
\end{align*}

\label{lem:taunormplus}
 Consider the stopping time $ \tau^{+}_{\gamma} $ defined in \cref{def:stopping times}.
 Let $C>\mathrm{e}^{-1}$ and $\varepsilon\in(0,1)$ be arbitrary positive constants and suppose $\frac{C^2\lg^2n}{n}\leq x_{\gamma}\leq 1-\varepsilon$.
 Then,
 \begin{align*} 
    \Pr\qty[ \tau^{+}_{\gamma} \ge T ] \le 
    \begin{cases}
     \frac{64\mathrm{e}^2}{\varepsilon}\cdot  \frac{x_{\gamma} n}{T}	& \text{for 3-Majority},\\[10pt]
     \frac{192\mathrm{e}^2}{\varepsilon^2}\cdot  \frac{x_{\gamma} n^2}{T}	& \text{for 2-Choices}.
    \end{cases}
 \end{align*}

    \label{lem:taunormplus OST}
    Consider 3-Majority or 2-Choices.
    Suppose $x_{\gamma}\leq 1-\varepsilon$ for a positive constant $\varepsilon\in (0,1)$.
Let $R_{\gamma}$ be a positive parameter defined by
\begin{align*}
    R_{\gamma}=
    \begin{cases*}
        \frac{\varepsilon}{n} & \text{for 3-Majority},\\
        \frac{\varepsilon^2}{3n^2} & \text{for 2-Choices}.
    \end{cases*}
\end{align*}
Then, 
\begin{align*}
    \mathbb{E}\qty[\tau^{+}_{\gamma}]
    \leq \frac{\mathbb{E}\qty[\gamma_{\tau^{+}_{\gamma}}]}{R_{\gamma}}.
\end{align*}

Let $\tau=\tau^{+}_{\gamma}$, $X_t=R_{\gamma} t-\gamma_t$ and $Y_t=X_{t\wedge \tau}$.
Then, from the definition of $R_{\gamma}$ and \cref{item:expectation of alphanorm} of \cref{lem:basic inequality},
\begin{align*}
\mathbb{E}_{t-1}\qty[Y_t-Y_{t-1}]
&=\mathbf{1}_{\tau>t-1}\qty(R_{\gamma} t-\mathbb{E}_{t-1}[\gamma_t]-R_{\gamma} (t-1)+\gamma_{t-1})
=\mathbf{1}_{\tau>t-1}\qty(\gamma_{t-1}+R_{\gamma}-\mathbb{E}_{t-1}[\gamma_t])
\leq 0,
\end{align*}
i.e., $(Y_t)_{t\in \mathbb{N}_0}$ is a supermartingale.
Note that, for 2-Choices, 
$\mathbb{E}_{t-1}\qty[\gamma_t]-\gamma_{t-1}\geq \frac{(1-\sqrt{1-\varepsilon})\varepsilon}{n^2}\geq \frac{\varepsilon^2}{3n}$ from $1-\sqrt{1-\varepsilon}\geq 1-\exp(-\varepsilon/2) \geq 1-\frac{1}{1+\varepsilon/2}\geq \frac{\varepsilon}{3}$.

From the optimal stopping theorem (\cref{thm:OST}), we have $\mathbb{E}[Y_\tau]\leq \mathbb{E}[Y_0]=-\gamma_0\leq 0$ 
Furthermore, $\mathbb{E}[Y_\tau]=\mathbb{E}[X_\tau]=R_{\gamma} \mathbb{E}[\tau]-\mathbb{E}[\gamma_\tau]$ holds.
Thus, 
\begin{align*}
    \mathbb{E}[\tau]&=\frac{\mathbb{E}[Y_\tau]+\mathbb{E}[\gamma_\tau]}{R_{\gamma}}
    \leq \frac{\mathbb{E}[\gamma_\tau]}{R_{\gamma}}
\end{align*}
holds and we obtain the claim.

\label{lem:taunormplus expectation of norm}
Consider the stopping time $\tau^{+}_{\gamma}$ defined in \cref{def:stopping times}.
For any positive parameter $C$, 
\begin{align*}
    \mathbb{E}\qty[\gamma_{\tau^{+}_{\gamma}}]\leq 
    16\mathrm{e}^2\qty(x_{\gamma}+\frac{C^2\lg^2n}{n})+2n^{-4\mathrm{e} C+1}\mathbb{E}\qty[\tau^{+}_{\gamma}].
\end{align*}

In the following, write $\tau=\tau^{+}_{\gamma}$ for convenience.

\paragraph{3-Majority.}
From \cref{lem:taunormplus OST,lem:taunormplus expectation of norm}, the following holds for a sufficiently large $n$:
\begin{align*}
    \mathbb{E}[\tau]
    &\leq \frac{n}{\varepsilon}\cdot \qty(16\mathrm{e}^2\qty(x_{\gamma}+\frac{C^2\lg^2n}{n})+2n^{-4\mathrm{e} C+1}\mathbb{E}[\tau])
    \leq \frac{32\mathrm{e}^2}{\varepsilon}x_{\gamma} n +\frac{1}{2}\mathbb{E}[\tau]
\end{align*}
Hence, $\mathbb{E}[\tau]\leq \frac{64\mathrm{e}^2}{\varepsilon}x_{\gamma} n$ and we obtain the claim from the Markov inequality.

\paragraph{2-Choices.}
From \cref{lem:taunormplus OST,lem:taunormplus expectation of norm}, the following holds for a sufficiently large $n$:
\begin{align*}
    \mathbb{E}[\tau]
    &\leq \frac{3n^2}{\varepsilon^2}\cdot \qty(16\mathrm{e}^2\qty(x_{\gamma}+\frac{C^2\lg^2n}{n})+2n^{-4\mathrm{e} C+1}\mathbb{E}[\tau])
    \leq \frac{96\mathrm{e}^2}{\varepsilon^2}x_{\gamma} n^2 +\frac{1}{2}\mathbb{E}[\tau].
\end{align*}
Hence, $\mathbb{E}[\tau]\leq \frac{192\mathrm{e}^2}{\varepsilon^2}x_{\gamma} n^2$ and we obtain the claim from the Markov inequality.

