\label{thm:Chernoff}
Let $X_1, \ldots, X_N$ be independent $[0,1]$-valued random variables and let $X=\sum_{i=1}^NX_i$.
Then, for any $z\geq 2\mathrm{e}\mathbb{E}[X]$, we have
\begin{align*}
  \Pr\sbra*{X\geq z}\leq 2^{-z}.
\end{align*}

\label{thm:Bernstein}
Let $X_1, \ldots, X_N$ be independent mean-zero random variables such that $\abs*{X_i}\leq D$ for all $i$.
Let $X=\sum_{i=1}^NX_i$.
Then, for any $z\geq 0$, we have
\begin{align*}
  \Pr\sbra*{\abs*{X}\geq z}\leq 2\exp\left(-\frac{z^2/2}{\mathbf{Var}[X]+D z/3}\right).
\end{align*}

\label{lem:zero one lemma}
Let $X_1,\ldots,X_n$ be random variables taking values in $\{0,1 \}$ such that $\sum_{i\in[n]}X_i=1$.
Then $X_1,\ldots,X_n$ are negatively associated.

\label{lem:Stochastic domination}
We have the following:
\begin{enumerate}
    \item If $X\preceq Y$, then $\mathbb{E}[f(X)]\leq \mathbb{E}[f(Y)]$ for any non-decreasing function $f:\mathbb{R}\to \mathbb{R}$.
    \item If $X\leq Y$, then $X\preceq Y$.
    \item If $X$ and $Y$ are identically distributed, then $X\preceq Y$.
\end{enumerate}

\label{lem:binomial dominance}
We have the following:
\begin{enumerate}
    \item If $X\sim \mathrm{Bin}(n,p)$ and $Y\sim \mathrm{Bin}(n,q)$ for $p\leq q$, then $X\preceq Y$.
    \item If $X\sim \mathrm{Bin}(n,p)$ and $Y\sim \mathrm{Bin}(m,p)$ for $n\leq m$, then $X\preceq Y$.
\end{enumerate}

\label{lem:concentration exponentially decay}
   Let $ X^{(1)},\dots,X^{(m)} $ be i.i.d.\ $ \mathbb{Z}_{\ge 0} $-valued random variables such that for some $ a,b>0 $ and any $ \ell\in \mathbb{Z}_{\ge 0} $,
   \begin{align*}
       \Pr\qty[ X^{(1)} = \ell ] \le a\cdot (1-b)^{\ell}.
   \end{align*}
   Let $ X = X^{(1)} + \dots + X^{(m)} $ and $ \mu = \mathbb{E}[X] $.
   Then, for some $ C=C(a,b) > 0$ and for any $ \gamma > 0$, we have
   \begin{align*}
       \Pr\qty[ X \ge (1+\gamma) \mu + Cm ] \le \exp\qty( -\frac{\gamma^2 m}{2(1+\gamma)} ).
   \end{align*}

