        &\leq \frac{1}{n^2}\sum_{i\in [k]}\sum_{t=1}^\infty\mathbb{E}\qty[\mathbf{1}_{\tau>t-1}n^{-4\mathrm{e} C+2}]\\
        &\leq n^{-4\mathrm{e} C+1}\mathbb{E}[\tau].
    \end{align*}

\begin{align*}
        &\mathbb{E}\qty[A_t(i)^2\mathbf{1}_{\tau=t}\mathbf{1}_{A_{t-1}(i)< C\lg n}\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}] \\
        &\leq \mathbb{E}\qty[A_t(i)^2\mathbf{1}_{\tau>t-1}\mathbf{1}_{A_{t-1}(i)< C\lg n}\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}] \\
        &\leq \mathbb{E}\qty[\mathbf{1}_{\tau>t-1}\mathbf{1}_{A_{t-1}(i)< C\lg n}\mathbb{E}_{t-1}\qty[A_t(i)^2\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}]].
    \end{align*}

\begin{align*}
        \mathbb{E}_{t-1}\qty[A_t(i)^2\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}]
        &=\sum_{\ell=1}^{\infty}\Pr_{t-1}\qty[A_t(i)^2\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}\geq \ell]\\
        &=\sum_{\ell=1}^{n^2}\Pr_{t-1}\qty[A_t(i)^2\geq \ell \textrm{ and } A_{t}(i)\geq 4\mathrm{e} C\lg n]\\
        &\leq n^2\Pr_{t-1}\qty[A_{t}(i)\geq 4\mathrm{e} C\lg n]\\
        &\leq n^2 2^{-4\mathrm{e} C\lg n} &&(\because \mathrm{\cref{thm:Chernoff}})\\
        &=n^{-4\mathrm{e} C+2}
    \end{align*}

\begin{align*}
        \frac{1}{n^2}\sum_{i\in [k]}\sum_{t=1}^\infty\mathbb{E}\qty[A_t(i)^2\mathbf{1}_{\tau=t}\mathbf{1}_{A_{t-1}(i)< C\lg n}\mathbf{1}_{A_{t}(i)\geq 4\mathrm{e} C\lg n}]
        &\leq \frac{1}{n^2}\sum_{i\in [k]}\sum_{t=1}^\infty\mathbb{E}\qty[\mathbf{1}_{\tau>t-1}n^{-4\mathrm{e} C+2}]\\
        &\leq n^{-4\mathrm{e} C+1}\mathbb{E}[\tau].
    \end{align*}

\begin{align*}
        \Pr\qty[ S = \ell \;\middle\vert\; S\le K] &\le \frac{\Pr\qty[S=\ell]}{\Pr\qty[S\le K]} \\
        &\le O(1)\cdot \Pr\qty[ S=\ell \;\middle\vert\; S\ge \ell ] \\
        &=\Pr\qty[\text{phase $\ell$ is bad} \;\middle\vert\; \text{phases $0,\dots,\ell-1$ are good}] \\
        &\le \begin{cases}
            \exp(-C_2 (1+c_\varphi^{\uparrow})^{2\ell-2}\cdot x_0^2) & \text{if $\ell\ge 1$} \\
            1-C_1 & \text{if $\ell=0$}
        \end{cases} \\
        &\le p^\ell.  & & \text{for some $ p <1$}
    \end{align*}
